#!/usr/bin/env node
// Post-processes the package generated by `wasm-pack build` so that the license
// texts and third-party notices ship with the compiled WebAssembly binary.
//
// wasm-pack's generated package.json lists only the .wasm/.js/.d.ts files, so a
// published tarball would otherwise contain the binary without any license or
// notice. This script copies the files in and adds them to "files". Idempotent.
//
// Usage (from the repository root, after `wasm-pack build core/clasp-wasm ...`):
//   node scripts/finalize-wasm-package.mjs [pkgDir]     # default: core/clasp-wasm/pkg

import { execSync } from "node:child_process";
import { copyFileSync, existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const crateDir = join(root, "core", "clasp-wasm");
const pkgDir = resolve(process.argv[2] ?? join(crateDir, "pkg"));

const SHIPPED_DOCS = ["LICENSE-MIT", "LICENSE-APACHE", "THIRD-PARTY-NOTICES.md"];

const pkgJsonPath = join(pkgDir, "package.json");
if (!existsSync(pkgJsonPath)) {
  console.error(`package.json not found in ${pkgDir}; run wasm-pack build first.`);
  process.exit(1);
}

for (const name of SHIPPED_DOCS) {
  const src = join(crateDir, name);
  if (!existsSync(src)) {
    console.error(`missing ${src}; regenerate with scripts/generate-third-party-notices.mjs`);
    process.exit(1);
  }
  copyFileSync(src, join(pkgDir, name));
}

const pkg = JSON.parse(readFileSync(pkgJsonPath, "utf8"));
const files = new Set(pkg.files ?? []);
for (const name of SHIPPED_DOCS) files.add(name);
pkg.files = [...files];
writeFileSync(pkgJsonPath, JSON.stringify(pkg, null, 2) + "\n", "utf8");

// Verify against what npm would really publish (dry run: nothing is uploaded).
const packed = JSON.parse(
  execSync("npm pack --dry-run --json", { cwd: pkgDir, encoding: "utf8" }),
);
const tarballPaths = new Set(packed[0].files.map((f) => f.path));
const absent = SHIPPED_DOCS.filter((name) => !tarballPaths.has(name));
if (absent.length > 0) {
  console.error(`npm tarball is missing: ${absent.join(", ")}`);
  process.exit(1);
}

console.log(`finalized ${pkgDir}: files = ${pkg.files.join(", ")}`);
console.log(`verified tarball contains: ${SHIPPED_DOCS.join(", ")}`);
